interesting = []
for f in files:
    try:
        lines = open(f, errors="ignore").read().splitlines()
    except Exception: continue
    start=None; fname=None; funcs=[]
    for i,l in enumerate(lines):
        if re.match(r'^\{', l) and fname is None:
            prev = lines[i-1].strip() if i>0 else ""
            if '(' in prev:
                fname = prev; start = i
        if start is not None and re.match(r'^\}', l):
            funcs.append((fname,start,i)); fname=None; start=None
    for (fn,s,e) in funcs:
        body = lines[s:e+1]
        pulls = [j+s for j,l in enumerate(body) if realloc.search(l)]
        if not pulls: continue
        for j,l in enumerate(body):
            dm = re.match(r'^\t(?:const\s+)?(?:struct\s+\w+|unsigned char|char|void)\s*\*\s*(\w+)\s*=\s*(.+);', l)
            if not dm: continue
            var, rhs = dm.group(1), dm.group(2)
            if not re.search(r'skb|hdr|data|frag|p->|gro|->data', rhs): continue
            cap = j+s
            for pu in pulls:
