                    for k in range(pu+1, e+1):
                        if re.search(r'\b'+re.escape(var)+r'\b\s*(->|\[|\.)|->\s*'+re.escape(var)+r'\b', lines[k]):
                            interesting.append((f,fn,cap+1,pu+1,k+1,var,lines[cap].strip()[:70],lines[k].strip()[:70]))
                            break
                    break
for t in interesting:
    print(f"{t[0]}:{t[2]} fn={t[1][:50]!r} cap[{t[5]}] pull@{t[3]} use@{t[4]} :: {t[6]}  ==> {t[7]}")
print("TOTAL", len(interesting))
